sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    //Type appropriate comment here, and begin script below
    var mincidentnumber = g_form.getValue('sys_display.original.problem.first_reported_by_task');
    var ga = new GlideAjax('mdssgetincidentstate');
    ga.addParam('sysparm_name', 'getIncidentState');
    ga.addParam('sysparm_num', mincidentnumber);
    // alert(mincidentnumber);
    ga.getXMLAnswer(echoCallBack);

    function echoCallBack(answer) {
        g_form.addInfoMessage(
            'State of Incident from server using getXMLAnswer: ' + answer);

    }

}
